"use client";

import type { ComponentProps, ReactNode } from "react";
import { CloudUpload } from "lucide-react";
import { useTranslations } from "@fuma-translate/react";
import {
  useUploadControls,
  useMultiUploadControls,
  type UseUploadControlsOptions,
  type UseMultiUploadControlsOptions,
  type UploadProgress,
  type MultiUploadFileState,
} from "@dimah-s3/react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import { resolveStatusSlot, type StatusSlot } from "@/registry/dimah-s3-ui/lib/status-slot";
import { Button } from "@/registry/dimah-s3-ui/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/registry/dimah-s3-ui/components/ui/tooltip";
import { UploadStatusBlock } from "@/registry/dimah-s3-ui/components/dimah-s3/upload/upload-status-block";
import { useUploadToast, type UploadToastCtrl } from "@/registry/dimah-s3-ui/hooks/use-upload-toast";

const EMPTY_PROGRESS: UploadProgress = { loaded: 0, total: 0, percent: 0 };
const EMPTY_FILES: MultiUploadFileState[] = [];

/** Props for {@link UploadButton}. Extends {@link UseUploadControlsOptions} or {@link UseMultiUploadControlsOptions}. */
export type UploadButtonProps = (
  UseUploadControlsOptions | UseMultiUploadControlsOptions
) & {
  className?: string;
  /** Button label. */
  label?: string;
  /** Custom button content. Replaces default icon + label. */
  children?: ReactNode;
  disabled?: boolean;
  tooltipText?: string;
  /** Show toasts during upload. @default true */
  toast?: boolean;
  /**
   * Inline status control.
   * - `true` (default): render below the button
   * - `false`: hide status
   * - `(node) => ReactNode`: wrap or relocate the status node
   */
  status?: StatusSlot;
  /**
   * Force multi-file mode. When omitted, multi mode is inferred from
   * `maxFiles > 1`.
   */
  multiple?: boolean;
  /** Button variant. @default "default" */
  variant?: ComponentProps<typeof Button>["variant"];
  /** Button size. @default "default" */
  size?: ComponentProps<typeof Button>["size"];
  /** Extra classes on the trigger button element. */
  buttonClassName?: string;
};

export function UploadButton({
  className,
  label,
  children,
  disabled,
  tooltipText,
  toast: enableToast = true,
  status: statusSlot = true,
  multiple,
  variant = "default",
  size = "default",
  buttonClassName,
  ...options
}: UploadButtonProps) {
  const t = useTranslations();
  const isMulti =
    multiple === true ||
    ((options as UseMultiUploadControlsOptions).maxFiles ?? 1) > 1;

  // Both hooks must be called unconditionally (React rules of hooks).
  // Only the active mode's output is used.
  const single = useUploadControls(options as UseUploadControlsOptions);
  const multi = useMultiUploadControls(
    options as UseMultiUploadControlsOptions,
  );

  const canPause = options.uploadStore != null && options.uploadStore !== false;

  const ctrl: UploadToastCtrl = isMulti
    ? {
        mode: "multi",
        phase: multi.phase,
        files: multi.files,
        totalProgress: multi.totalProgress,
        error: multi.error,
        cancel: multi.cancel,
      }
    : {
        mode: "single",
        phase: single.phase,
        fileInfo: single.fileInfo,
        progress: single.progress,
        error: single.error,
        cancel: single.cancel,
      };

  const isDisabled =
    disabled || (isMulti ? multi.isUploading : single.isUploading);

  useUploadToast(ctrl, enableToast);

  const statusNode =
    statusSlot === false ? null : isMulti ? (
      <UploadStatusBlock
        mode="multi"
        phase={multi.phase}
        files={multi.files ?? EMPTY_FILES}
        totalProgress={multi.totalProgress ?? EMPTY_PROGRESS}
        error={multi.error}
        onCancel={multi.cancel}
        onPause={canPause ? multi.detach : undefined}
      />
    ) : (
      <UploadStatusBlock
        mode="single"
        phase={single.phase}
        progress={single.progress}
        error={single.error}
        fileInfo={single.fileInfo}
        onCancel={single.cancel}
        onPause={canPause ? single.detach : undefined}
      />
    );

  const status = resolveStatusSlot(statusSlot, statusNode);

  const openFilePicker = isMulti ? multi.openFilePicker : single.openFilePicker;
  const inputProps = isMulti ? multi.inputProps : single.inputProps;

  const buttonLabel =
    label ??
    (isMulti
      ? t("Upload files", { note: "button" })
      : t("Upload file", { note: "button" }));
  const buttonContent = children ?? (
    <>
      <CloudUpload data-icon="inline-start" />
      {buttonLabel}
    </>
  );

  const button = (
    <Button
      variant={variant}
      size={size}
      className={buttonClassName}
      disabled={isDisabled}
      onClick={openFilePicker}
    >
      {buttonContent}
    </Button>
  );

  return (
    <div className={cn("inline-flex flex-col gap-2", className)}>
      <div className="inline-flex items-center gap-2">
        <input {...inputProps} />
        {tooltipText ? (
          <Tooltip>
            <TooltipTrigger render={button} />
            <TooltipContent>{tooltipText}</TooltipContent>
          </Tooltip>
        ) : (
          button
        )}
      </div>
      {status}
    </div>
  );
}

"use client";

import { formatFileSize } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { formatEta } from "@dimah-s3/react";
import type {
  UploadFileInfo,
  UploadPhase,
  UploadProgress,
} from "@dimah-s3/react";
import { FileAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/file-attachment";
import { StatusAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/status-attachment";

export type UploadStatusProps = {
  phase: UploadPhase;
  progress: UploadProgress;
  error: string | null;
  fileInfo: UploadFileInfo | null;
  onCancel?: () => void;
  /** When set (typically with an `uploadStore`), shows a pause control. */
  onPause?: () => void;
  className?: string;
};

export function UploadStatus({
  phase,
  progress,
  error,
  fileInfo,
  onCancel,
  onPause,
  className,
}: UploadStatusProps) {
  const t = useTranslations();

  if (phase === "idle") return null;

  if (phase === "uploading" && fileInfo) {
    const eta =
      progress.speed && progress.total
        ? formatEta(progress.total - progress.loaded, progress.speed)
        : null;

    return (
      <FileAttachment
        state="uploading"
        fileName={fileInfo.name}
        fileSize={fileInfo.size}
        previewUrl={fileInfo.previewUrl}
        percent={progress.percent}
        description={
          eta ? `${eta} · ${formatFileSize(fileInfo.size)}` : undefined
        }
        onCancel={onCancel}
        onPause={onPause}
        className={className}
      />
    );
  }

  if (phase === "success" && fileInfo) {
    return (
      <FileAttachment
        state="done"
        fileName={fileInfo.name}
        fileSize={fileInfo.size}
        previewUrl={fileInfo.previewUrl}
        className={className}
      />
    );
  }

  if (phase === "error") {
    if (fileInfo) {
      return (
        <FileAttachment
          state="error"
          fileName={fileInfo.name}
          fileSize={fileInfo.size}
          previewUrl={fileInfo.previewUrl}
          error={error}
          className={className}
        />
      );
    }

    return (
      <StatusAttachment
        state="error"
        title={t("Upload failed", { note: "status" })}
        description={error ?? undefined}
        className={className}
      />
    );
  }

  if (phase === "validating" || phase === "presigning") {
    if (fileInfo) {
      return (
        <FileAttachment
          state="processing"
          fileName={fileInfo.name}
          fileSize={fileInfo.size}
          previewUrl={fileInfo.previewUrl}
          description={t("Preparing…", { note: "upload status" })}
          className={className}
        />
      );
    }

    return (
      <StatusAttachment
        state="processing"
        title={t("Preparing…", { note: "upload status" })}
        className={className}
      />
    );
  }

  return null;
}

"use client";

import { XIcon } from "lucide-react";
import { useTranslations } from "@fuma-translate/react";
import { formatEta } from "@dimah-s3/react";
import type {
  UploadProgress,
  MultiUploadFileState,
  MultiUploadPhase,
} from "@dimah-s3/react";
import { FileAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/file-attachment";
import { StatusAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/status-attachment";
import { AttachmentAction } from "@/registry/dimah-s3-ui/components/ui/attachment";
import type { AttachmentState } from "@/registry/dimah-s3-ui/lib/attachment-state";
import {
  Progress,
  ProgressLabel,
  ProgressValue,
} from "@/registry/dimah-s3-ui/components/ui/progress";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";

export type MultiUploadStatusProps = {
  phase: MultiUploadPhase;
  files: MultiUploadFileState[];
  totalProgress: UploadProgress;
  error: string | null;
  onCancel?: () => void;
  className?: string;
};

export function MultiUploadStatus({
  phase,
  files,
  totalProgress,
  error,
  onCancel,
  className,
}: MultiUploadStatusProps) {
  const t = useTranslations();

  if (phase === "idle") return null;

  if (phase === "uploading") {
    const eta =
      totalProgress.speed && totalProgress.total
        ? formatEta(
            totalProgress.total - totalProgress.loaded,
            totalProgress.speed,
          )
        : null;

    return (
      <div className={cn("flex w-full flex-col gap-2", className)}>
        <div className="flex w-full items-center gap-1.5">
          <Progress value={totalProgress.percent} className="flex-1">
            <ProgressLabel>
              {t("{done}/{total} files", {
                note: "upload progress",
                variables: {
                  done: String(
                    files.filter((f) => f.status === "success").length,
                  ),
                  total: String(files.length),
                },
              })}
              {eta ? (
                <span className="font-normal text-muted-foreground">
                  {" "}
                  · {eta}
                </span>
              ) : null}
            </ProgressLabel>
            <ProgressValue />
          </Progress>
          {onCancel ? (
            <AttachmentAction
              className="shrink-0"
              aria-label={t("Cancel", { note: "upload control" })}
              onClick={(e) => {
                e.stopPropagation();
                onCancel();
              }}
            >
              <XIcon />
            </AttachmentAction>
          ) : null}
        </div>
        <FileList files={files} />
      </div>
    );
  }

  if (phase === "success") {
    return (
      <div className={cn("flex w-full flex-col gap-2", className)}>
        <StatusAttachment
          state="done"
          title={t("All {count} file(s) uploaded", {
            note: "status",
            variables: { count: String(files.length) },
          })}
        />
        <FileList files={files} />
      </div>
    );
  }

  if (phase === "error") {
    return (
      <div className={cn("flex w-full flex-col gap-2", className)}>
        <StatusAttachment
          state="error"
          title={t("Upload failed", { note: "status" })}
          description={error ?? undefined}
        />
        {files.length > 0 ? <FileList files={files} /> : null}
      </div>
    );
  }

  if (phase === "validating") {
    return (
      <StatusAttachment
        state="processing"
        title={t("Validating…", { note: "upload status" })}
        className={className}
      />
    );
  }

  return null;
}

function fileAttachmentState(
  status: MultiUploadFileState["status"],
): AttachmentState {
  switch (status) {
    case "pending":
      return "idle";
    case "uploading":
      return "uploading";
    case "error":
      return "error";
    case "success":
      return "done";
  }
}

function FileList({ files }: { files: MultiUploadFileState[] }) {
  return (
    <div className="flex w-full flex-col gap-2">
      {files.map((f) => (
        <FileAttachment
          key={f.id}
          state={fileAttachmentState(f.status)}
          fileName={f.fileName}
          fileSize={f.fileSize}
          previewUrl={f.previewUrl}
          percent={f.progress.percent}
          error={f.error}
        />
      ))}
    </div>
  );
}

"use client";

import type {
  UploadFileInfo,
  UploadPhase,
  UploadProgress,
  MultiUploadFileState,
  MultiUploadPhase,
} from "@dimah-s3/react";
import { UploadStatus } from "@/registry/dimah-s3-ui/components/dimah-s3/upload/upload-status";
import { MultiUploadStatus } from "@/registry/dimah-s3-ui/components/dimah-s3/upload/multi-upload-status";

export type UploadStatusBlockProps =
  | {
      mode: "single";
      phase: UploadPhase;
      progress: UploadProgress;
      error: string | null;
      fileInfo: UploadFileInfo | null;
      onCancel?: () => void;
      onPause?: () => void;
    }
  | {
      mode: "multi";
      phase: MultiUploadPhase;
      files: MultiUploadFileState[];
      totalProgress: UploadProgress;
      error: string | null;
      onCancel?: () => void;
      onPause?: () => void;
    };

export function UploadStatusBlock(props: UploadStatusBlockProps) {
  if (props.mode === "multi" && props.files.length === 1) {
    const f = props.files[0];
    return (
      <UploadStatus
        phase={props.phase}
        progress={f.progress}
        error={f.error ?? props.error}
        fileInfo={{
          name: f.fileName,
          size: f.fileSize,
          type: f.fileType,
          previewUrl: f.previewUrl,
        }}
        onCancel={props.onCancel}
        onPause={props.onPause}
      />
    );
  }

  if (props.mode === "multi") {
    return (
      <MultiUploadStatus
        phase={props.phase}
        files={props.files}
        totalProgress={props.totalProgress}
        error={props.error}
        onCancel={props.onCancel}
      />
    );
  }
  return (
    <UploadStatus
      phase={props.phase}
      progress={props.progress}
      error={props.error}
      fileInfo={props.fileInfo}
      onCancel={props.onCancel}
      onPause={props.onPause}
    />
  );
}

"use client";

import type { ReactNode } from "react";
import {
  AlertCircleIcon,
  CheckCircleIcon,
  PauseIcon,
  XIcon,
} from "lucide-react";
import { formatFileSize, truncateFileName } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/registry/dimah-s3-ui/components/ui/attachment";
import { CircleProgress } from "@/registry/dimah-s3-ui/components/dimah-s3/circle-progress";
import type { AttachmentState } from "@/registry/dimah-s3-ui/lib/attachment-state";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";

/** @deprecated Use {@link AttachmentState}. */
export type FileAttachmentState = AttachmentState;

export type { AttachmentState };

export type FileAttachmentProps = {
  state: AttachmentState;
  fileName: string;
  fileSize?: number;
  /** Image thumbnail URL — enables `AttachmentMedia variant="image"`. */
  previewUrl?: string | null;
  /** Progress 0–100 when `state` is uploading/idle (pending). */
  percent?: number;
  /** Secondary line; defaults to size, or error text when `state="error"`. */
  description?: ReactNode;
  error?: string | null;
  onCancel?: () => void;
  onPause?: () => void;
  className?: string;
};

export function FileAttachment({
  state,
  fileName,
  fileSize,
  previewUrl,
  percent = 0,
  description,
  error,
  onCancel,
  onPause,
  className,
}: FileAttachmentProps) {
  const t = useTranslations();
  const hasPreview = Boolean(previewUrl);

  const resolvedDescription =
    description ??
    (state === "error"
      ? (error ?? t("Upload failed", { note: "status" }))
      : fileSize != null
        ? formatFileSize(fileSize)
        : null);

  const showActions =
    (state === "uploading" || state === "processing") &&
    (onCancel != null || onPause != null);

  const iconMedia =
    state === "done" ? (
      <CheckCircleIcon />
    ) : state === "error" ? (
      <AlertCircleIcon />
    ) : (
      <CircleProgress
        percent={state === "uploading" ? percent : 0}
        size={14}
        strokeWidth={2}
        className="size-3.5"
      />
    );

  return (
    <Attachment
      state={state}
      size="sm"
      orientation="horizontal"
      className={cn("w-full max-w-full", className)}
    >
      {hasPreview ? (
        <AttachmentMedia variant="image">
          <img src={previewUrl!} alt="" />
          {state === "uploading" ||
          state === "processing" ||
          state === "idle" ? (
            <div className="absolute inset-0 flex items-center justify-center bg-background/50">
              <CircleProgress
                percent={state === "uploading" ? percent : 0}
                size={16}
                strokeWidth={2}
                className="size-4"
              />
            </div>
          ) : null}
          {state === "error" ? (
            <div className="absolute inset-0 flex items-center justify-center bg-destructive/20 text-destructive">
              <AlertCircleIcon className="size-4" />
            </div>
          ) : null}
        </AttachmentMedia>
      ) : (
        <AttachmentMedia>{iconMedia}</AttachmentMedia>
      )}
      <AttachmentContent>
        <AttachmentTitle className="max-w-[30ch]">
          {truncateFileName(fileName)}
        </AttachmentTitle>
        {resolvedDescription != null ? (
          <AttachmentDescription
            className={
              state === "error"
                ? "overflow-visible whitespace-normal [overflow-wrap:anywhere]"
                : undefined
            }
          >
            {resolvedDescription}
          </AttachmentDescription>
        ) : null}
      </AttachmentContent>
      {showActions ? (
        <AttachmentActions>
          {onPause ? (
            <AttachmentAction
              aria-label={t("Pause", { note: "upload control" })}
              onClick={(e) => {
                e.stopPropagation();
                onPause();
              }}
            >
              <PauseIcon />
            </AttachmentAction>
          ) : null}
          {onCancel ? (
            <AttachmentAction
              aria-label={t("Cancel", { note: "upload control" })}
              onClick={(e) => {
                e.stopPropagation();
                onCancel();
              }}
            >
              <XIcon />
            </AttachmentAction>
          ) : null}
        </AttachmentActions>
      ) : null}
    </Attachment>
  );
}

"use client";

import { cn } from "@/registry/dimah-s3-ui/lib/utils";

export function CircleProgress({
  percent,
  size = 20,
  strokeWidth = 2.5,
  className,
}: {
  percent: number;
  size?: number;
  strokeWidth?: number;
  className?: string;
}) {
  const r = (size - strokeWidth) / 2;
  const c = 2 * Math.PI * r;
  const offset = c - (percent / 100) * c;
  return (
    <svg
      width={size}
      height={size}
      className={cn("shrink-0 -rotate-90", className)}
      style={{ width: size, height: size }}
    >
      <circle
        cx={size / 2}
        cy={size / 2}
        r={r}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        className="text-muted-foreground/20"
      />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={r}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeDasharray={c}
        strokeDashoffset={offset}
        strokeLinecap="round"
        className="text-primary transition-[stroke-dashoffset] duration-200"
      />
    </svg>
  );
}

"use client";

import { useEffect, useLayoutEffect, useRef } from "react";
import { formatFileSize } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import type {
  UploadFileInfo,
  UploadProgress,
  MultiUploadFileState,
} from "@dimah-s3/react";

import { toast } from "@/components/ui/toast";

export type UploadToastCtrl = {
  mode: "single" | "multi";
  phase: string;
  fileInfo?: UploadFileInfo | null;
  progress?: UploadProgress;
  files?: MultiUploadFileState[];
  totalProgress?: UploadProgress;
  error: string | null;
  cancel: () => void;
};

function sizeNode(size: number) {
  return (
    <span dir="ltr" className="inline-block whitespace-nowrap tabular-nums">
      {formatFileSize(size)}
    </span>
  );
}

function progressNode(loaded: number, total: number) {
  return (
    <span dir="ltr" className="inline-block whitespace-nowrap tabular-nums">
      {formatFileSize(loaded)} / {formatFileSize(total)}
    </span>
  );
}

/**
 * Drives toasts for upload progress/success/error.
 * Shared between UploadButton and UploadDropzone.
 */
export function useUploadToast(ctrl: UploadToastCtrl, enabled: boolean) {
  const t = useTranslations();
  const toastIdRef = useRef<string | null>(null);
  const prevPhaseRef = useRef(ctrl.phase);
  const cancelRef = useRef(ctrl.cancel);
  useLayoutEffect(() => {
    cancelRef.current = ctrl.cancel;
  });

  const { mode, phase, fileInfo, progress, files, totalProgress, error } = ctrl;

  // Phase-transition toasts (once per phase change)
  useEffect(() => {
    if (prevPhaseRef.current === phase) return;
    prevPhaseRef.current = phase;
    if (!enabled) return;

    const fileList = files ?? [];
    const isMulti = mode === "multi" && fileList.length > 1;
    const file =
      fileInfo ??
      (fileList.length === 1
        ? { name: fileList[0].fileName, size: fileList[0].fileSize }
        : null);
    const total = totalProgress?.total ?? 0;

    if (phase === "idle" && toastIdRef.current) {
      toast.close(toastIdRef.current);
      toastIdRef.current = null;
    }
    if (phase === "success") {
      if (toastIdRef.current) toast.close(toastIdRef.current);
      if (isMulti) {
        toast.add({
          type: "success",
          title: t("{count} file(s) uploaded", {
            note: "toast",
            variables: { count: String(fileList.length) },
          }),
          description: sizeNode(total),
        });
      } else if (file) {
        toast.add({
          type: "success",
          title: t("Upload complete", { note: "toast" }),
          description: sizeNode(file.size),
        });
      }
      toastIdRef.current = null;
    }
    if (phase === "error") {
      if (toastIdRef.current) toast.close(toastIdRef.current);
      if (isMulti && fileList.length > 0) {
        const succeeded = fileList.filter((f) => f.status === "success").length;
        const failed = fileList.filter((f) => f.status === "error").length;
        toast.add({
          type: "error",
          title: t("Upload finished with errors", { note: "toast" }),
          description: (
            <span
              dir="ltr"
              className="inline-block whitespace-nowrap tabular-nums"
            >
              {t("{succeeded} succeeded, {failed} failed", {
                note: "toast",
                variables: {
                  succeeded: String(succeeded),
                  failed: String(failed),
                },
              })}
            </span>
          ),
        });
      } else {
        toast.add({
          type: "error",
          title: t("Upload failed", { note: "toast" }),
          description: (
            <span dir="auto" className="block [overflow-wrap:anywhere]">
              {error ??
                fileList[0]?.error ??
                t("Unknown error", { note: "fallback" })}
            </span>
          ),
        });
      }
      toastIdRef.current = null;
    }
  }, [enabled, phase, mode, fileInfo, files, totalProgress, error, t]);

  // Progress toast (updated on each progress tick)
  useEffect(() => {
    if (!enabled || phase !== "uploading") return;

    const fileList = files ?? [];
    const isMulti = mode === "multi" && fileList.length > 1;
    const file =
      fileInfo ??
      (fileList.length === 1
        ? { name: fileList[0].fileName, size: fileList[0].fileSize }
        : null);
    const total = totalProgress ?? { loaded: 0, total: 0, percent: 0 };
    const singleProgress =
      progress ??
      (fileList.length === 1
        ? fileList[0].progress
        : { loaded: 0, total: 0, percent: 0 });

    const payload = isMulti
      ? {
          type: "loading" as const,
          timeout: 0,
          title: t("Uploading {done}/{total}", {
            note: "toast",
            variables: {
              done: String(
                fileList.filter((f) => f.status === "success").length,
              ),
              total: String(fileList.length),
            },
          }),
          description: progressNode(total.loaded, total.total),
          actionProps: {
            children: t("Cancel", { note: "toast action" }),
            onClick: () => cancelRef.current(),
          },
        }
      : file
        ? {
            type: "loading" as const,
            timeout: 0,
            title: t("Uploading", { note: "toast" }),
            description: progressNode(singleProgress.loaded, file.size),
            actionProps: {
              children: t("Cancel", { note: "toast action" }),
              onClick: () => cancelRef.current(),
            },
          }
        : null;

    if (!payload) return;

    if (toastIdRef.current) {
      toast.update(toastIdRef.current, payload);
    } else {
      toastIdRef.current = toast.add(payload);
    }
  }, [enabled, phase, mode, fileInfo, files, progress, totalProgress, t]);
}

"use client";

import type { ReactNode } from "react";
import {
  AlertCircleIcon,
  CheckCircleIcon,
  LoaderCircleIcon,
} from "lucide-react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import {
  Attachment,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/registry/dimah-s3-ui/components/ui/attachment";
import type { AttachmentState } from "@/registry/dimah-s3-ui/lib/attachment-state";

/** @deprecated Use {@link AttachmentState}. */
export type StatusAttachmentState = AttachmentState;

export type { AttachmentState };

export type StatusAttachmentProps = {
  state: AttachmentState;
  title?: ReactNode;
  description?: ReactNode;
  media?: ReactNode;
  actions?: ReactNode;
  className?: string;
};

/**
 * Minimal Attachment shell for operation feedback (upload/download/delete).
 * Relies on Attachment `data-state` styles for error/done chrome.
 */
export function StatusAttachment({
  state,
  title,
  description,
  media,
  actions,
  className,
}: StatusAttachmentProps) {
  const defaultMedia =
    state === "error" ? (
      <AlertCircleIcon />
    ) : state === "done" ? (
      <CheckCircleIcon />
    ) : state === "processing" || state === "uploading" ? (
      <LoaderCircleIcon className="animate-spin" data-slot="spinner" />
    ) : null;

  return (
    <Attachment
      state={state}
      size="sm"
      orientation="horizontal"
      className={cn("w-full max-w-full", className)}
    >
      <AttachmentMedia>{media ?? defaultMedia}</AttachmentMedia>
      <AttachmentContent>
        {title != null ? (
          <AttachmentTitle className="max-w-[30ch]">{title}</AttachmentTitle>
        ) : null}
        {description != null ? (
          <AttachmentDescription
            className={
              state === "error"
                ? "overflow-visible whitespace-normal [overflow-wrap:anywhere]"
                : undefined
            }
          >
            {description}
          </AttachmentDescription>
        ) : null}
      </AttachmentContent>
      {actions ? <AttachmentActions>{actions}</AttachmentActions> : null}
    </Attachment>
  );
}

import type { ReactNode } from "react";

/**
 * Controls inline status rendering for wired UI components.
 *
 * - `true` (default): render the status node in the default slot
 * - `false`: hide status
 * - `(node) => ReactNode`: wrap or relocate the status node
 */
export type StatusSlot = boolean | ((node: ReactNode) => ReactNode);

/** Resolve a {@link StatusSlot} against a built status node. */
export function resolveStatusSlot(
  slot: StatusSlot = true,
  node: ReactNode,
): ReactNode {
  if (slot === false) return null;
  if (typeof slot === "function") return slot(node);
  return node;
}

